// k6 load test — UKBI 100 concurrent users with pre-generated auth tokens
// No login during test (tokens generated by scripts/seed-local-auth-tokens.ts)
// Ramp-up: 0 → 100 over 1 min, stay 3 min, ramp-down: 100 → 0 over 1 min
//
// Usage:
//   k6 run tests/load/ukbi-100-user.js \
//     -e BASE_URL=http://localhost:3000 \
//     -e PAKET_ID=local-ukbi-practice

import http from "k6/http";
import { check, sleep, group } from "k6";
import { Rate, Trend } from "k6/metrics";
import { SharedArray } from "k6/data";

const BASE_URL = __ENV.BASE_URL || "http://localhost:3000";
const PAKET_ID = __ENV.PAKET_ID || "local-ukbi-practice";

// Read pre-generated auth tokens at init stage
const tokenData = JSON.parse(open("./auth-tokens.json"));
const tokenList = new SharedArray("tokens", function () {
  const keys = Object.keys(tokenData).sort();
  return keys.map((k) => tokenData[k].token);
});

const fetchQuestionsDuration = new Trend("fetch_questions_duration");
const submitDuration = new Trend("submit_duration");
const resultDuration = new Trend("result_duration");

export const options = {
  stages: [
    { duration: "1m", target: 100 },
    { duration: "3m", target: 100 },
    { duration: "1m", target: 0 },
  ],
  thresholds: {
    http_req_duration: ["p(95)<5000"],
  },
};

function buildAuthHeaders(token) {
  return {
    "Content-Type": "application/json",
    "Authorization": `Bearer ${token}`,
  };
}

export default function () {
  // Pick token by VU index (pre-generated, no login needed)
  const token = tokenList[(__VU - 1) % tokenList.length];
  const headers = buildAuthHeaders(token);
  const startTime = Date.now();

  // Fetch questions
  let questions = [];
  group("Fetch Questions", function () {
    let res = http.get(`${BASE_URL}/api/kompetensi/${PAKET_ID}`, { headers });

    if (res.status === 400) {
      res = http.get(`${BASE_URL}/api/kompetensi/${PAKET_ID}?retry=1`, { headers });
    }

    check(res, {
      "fetch status 200": (r) => r.status === 200,
    });
    fetchQuestionsDuration.add(res.timings.duration);

    if (res.status === 200) {
      try {
        const d = JSON.parse(res.body);
        const data = d.data || d;
        for (const section of data.questions || []) {
          if (section.questions) {
            for (const q of section.questions) {
              questions.push(q);
            }
          }
        }
      } catch { /* ignore */ }
    }

    if (questions.length > 0) {
      sleep(Math.min(5, 0.5 + questions.length * 0.1));
    }
  });

  if (questions.length === 0) {
    sleep(1 + Math.random() * 2);
    return;
  }

  // Submit answers (70% chance)
  const doFullSim = Math.random() < 0.7;

  if (doFullSim) {
    group("Submit Answers", function () {
      const answers = {};
      for (const q of questions) {
        if (q.options?.length > 0) {
          answers[q.id] = q.options[0].id || "A";
        }
      }

      const timeSpent = Math.floor((Date.now() - startTime) / 1000);

      const submitRes = http.post(
        `${BASE_URL}/api/kompetensi/${PAKET_ID}/submit`,
        JSON.stringify({ answers, timeSpent }),
        { headers }
      );

      check(submitRes, {
        "submit status 200": (r) => r.status === 200,
      });
      submitDuration.add(submitRes.timings.duration);

      sleep(1);
    });

    group("View Result", function () {
      const res = http.get(
        `${BASE_URL}/api/kompetensi/${PAKET_ID}/hasil`,
        { headers }
      );

      check(res, {
        "result status 200": (r) => r.status === 200,
      });
      resultDuration.add(res.timings.duration);
    });
  }

  // Control iteration rate
  sleep(1 + Math.random() * 2);
}
